using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;

            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }

        public static SchoolContext CreateWithSeedData(string? dbName = null)
        {
            var context = Create(dbName);
            SeedData(context);
            return context;
        }

        private static void SeedData(SchoolContext context)
        {
            var instructors = new[]
            {
                new Instructor { ID = 1, LastName = "Smith", FirstMidName = "John", HireDate = new DateTime(2020, 1, 15), CourseAssignments = new List<CourseAssignment>() },
                new Instructor { ID = 2, LastName = "Jones", FirstMidName = "Jane", HireDate = new DateTime(2019, 6, 1), CourseAssignments = new List<CourseAssignment>() }
            };
            context.Instructors.AddRange(instructors);

            var departments = new[]
            {
                new Department { DepartmentID = 1, Name = "Engineering", Budget = 100000m, StartDate = new DateTime(2020, 9, 1), InstructorID = 1 },
                new Department { DepartmentID = 2, Name = "Science", Budget = 50000m, StartDate = new DateTime(2019, 9, 1), InstructorID = 2 }
            };
            context.Departments.AddRange(departments);

            var courses = new[]
            {
                new Course { CourseID = 101, Title = "Intro to CS", Credits = 3, DepartmentID = 1, Enrollments = new List<Enrollment>(), CourseAssignments = new List<CourseAssignment>() },
                new Course { CourseID = 102, Title = "Data Structures", Credits = 4, DepartmentID = 1, Enrollments = new List<Enrollment>(), CourseAssignments = new List<CourseAssignment>() },
                new Course { CourseID = 201, Title = "Physics 101", Credits = 3, DepartmentID = 2, Enrollments = new List<Enrollment>(), CourseAssignments = new List<CourseAssignment>() }
            };
            context.Courses.AddRange(courses);

            var students = new[]
            {
                new Student { ID = 1, LastName = "Doe", FirstMidName = "Alice", EnrollmentDate = new DateTime(2021, 9, 1), Enrollments = new List<Enrollment>() },
                new Student { ID = 2, LastName = "Brown", FirstMidName = "Bob", EnrollmentDate = new DateTime(2022, 1, 15), Enrollments = new List<Enrollment>() },
                new Student { ID = 3, LastName = "Adams", FirstMidName = "Charlie", EnrollmentDate = new DateTime(2021, 9, 1), Enrollments = new List<Enrollment>() }
            };
            context.Students.AddRange(students);

            var enrollments = new[]
            {
                new Enrollment { EnrollmentID = 1, CourseID = 101, StudentID = 1, Grade = Grade.A },
                new Enrollment { EnrollmentID = 2, CourseID = 102, StudentID = 1, Grade = Grade.B },
                new Enrollment { EnrollmentID = 3, CourseID = 101, StudentID = 2, Grade = Grade.C }
            };
            context.Enrollments.AddRange(enrollments);

            var courseAssignments = new[]
            {
                new CourseAssignment { CourseID = 101, InstructorID = 1 },
                new CourseAssignment { CourseID = 102, InstructorID = 1 },
                new CourseAssignment { CourseID = 201, InstructorID = 2 }
            };
            context.CourseAssignments.AddRange(courseAssignments);

            context.SaveChanges();
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain existing queue items from other tests (static queue)
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            _sut.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_EnqueuesNotification()
        {
            _sut.SendNotification("Student", "1", "Alice Doe", EntityOperation.CREATE, "Admin");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Equal("Student", result.EntityType);
            Assert.Equal("1", result.EntityId);
            Assert.Equal("CREATE", result.Operation);
            Assert.Equal("Admin", result.CreatedBy);
            Assert.False(result.IsRead);
            Assert.Contains("Alice Doe", result.Message);
            Assert.Contains("created", result.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_UsesEntityId()
        {
            _sut.SendNotification("Course", "42", EntityOperation.UPDATE);

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Contains("ID: 42", result.Message);
            Assert.Contains("updated", result.Message);
        }

        [Fact]
        public void SendNotification_WithoutUserName_DefaultsToSystem()
        {
            _sut.SendNotification("Student", "5", EntityOperation.DELETE);

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Equal("System", result.CreatedBy);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "created")]
        [InlineData(EntityOperation.UPDATE, "updated")]
        [InlineData(EntityOperation.DELETE, "deleted")]
        public void SendNotification_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
        {
            _sut.SendNotification("Department", "10", "Engineering", operation, "User1");

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.Contains(expectedVerb, result.Message);
            Assert.Contains("Engineering", result.Message);
        }

        [Fact]
        public void ReceiveNotification_EmptyQueue_ReturnsNull()
        {
            var result = _sut.ReceiveNotification();

            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_FIFO_Order()
        {
            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);

            var first = _sut.ReceiveNotification();
            var second = _sut.ReceiveNotification();

            Assert.Equal("A", first!.EntityType);
            Assert.Equal("B", second!.EntityType);
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // MarkAsRead is a no-op for in-memory, just verify no exception
            var ex = Record.Exception(() => _sut.MarkAsRead(999));
            Assert.Null(ex);
        }

        [Fact]
        public void SendNotification_SetsCreatedAtToNow()
        {
            var before = DateTime.Now.AddSeconds(-1);
            _sut.SendNotification("Test", "1", EntityOperation.CREATE);
            var after = DateTime.Now.AddSeconds(1);

            var result = _sut.ReceiveNotification();

            Assert.NotNull(result);
            Assert.InRange(result.CreatedAt, before, after);
        }
    }
}

using Xunit;

namespace ContosoUniversity.Tests.Helpers
{
    public class PaginatedListTests
    {
        [Fact]
        public void Create_ReturnsCorrectPage()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 2, 10);

            Assert.Equal(10, result.Count);
            Assert.Equal(11, result[0]);
            Assert.Equal(20, result[9]);
        }

        [Fact]
        public void Create_SetsPageIndex()
        {
            var source = Enumerable.Range(1, 30).AsQueryable();

            var result = PaginatedList<int>.Create(source, 3, 10);

            Assert.Equal(3, result.PageIndex);
        }

        [Fact]
        public void Create_CalculatesTotalPages()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(3, result.TotalPages);
        }

        [Theory]
        [InlineData(1, false)]
        [InlineData(2, true)]
        [InlineData(3, true)]
        public void HasPreviousPage_CorrectForPageIndex(int pageIndex, bool expected)
        {
            var source = Enumerable.Range(1, 30).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex, 10);

            Assert.Equal(expected, result.HasPreviousPage);
        }

        [Theory]
        [InlineData(1, true)]
        [InlineData(2, true)]
        [InlineData(3, false)]
        public void HasNextPage_CorrectForPageIndex(int pageIndex, bool expected)
        {
            var source = Enumerable.Range(1, 30).AsQueryable();

            var result = PaginatedList<int>.Create(source, pageIndex, 10);

            Assert.Equal(expected, result.HasNextPage);
        }

        [Fact]
        public void Create_LastPageHasRemainingItems()
        {
            var source = Enumerable.Range(1, 25).AsQueryable();

            var result = PaginatedList<int>.Create(source, 3, 10);

            Assert.Equal(5, result.Count);
        }

        [Fact]
        public void Create_EmptySource_ReturnsEmptyList()
        {
            var source = Enumerable.Empty<int>().AsQueryable();

            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Empty(result);
            Assert.Equal(0, result.TotalPages);
        }
    }
}

