using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Data
{
    public class SchoolContextTests
    {
        [Fact]
        public void CanAddAndRetrieveStudent()
        {
            using var context = TestDbContextFactory.Create();

            context.Students.Add(new Student
            {
                LastName = "Test",
                FirstMidName = "User",
                EnrollmentDate = new DateTime(2023, 1, 1),
                Enrollments = new List<Enrollment>()
            });
            context.SaveChanges();

            var student = context.Students.First();
            Assert.Equal("Test", student.LastName);
            Assert.Equal("User", student.FirstMidName);
        }

        [Fact]
        public void CanAddAndRetrieveCourse()
        {
            using var context = TestDbContextFactory.Create();

            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Test Dept",
                Budget = 10000m,
                StartDate = DateTime.Now
            };
            context.Departments.Add(dept);

            context.Courses.Add(new Course
            {
                CourseID = 500,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = 1,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            });
            context.SaveChanges();

            var course = context.Courses.Include(c => c.Department).First();
            Assert.Equal("Test Course", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal("Test Dept", course.Department.Name);
        }

        [Fact]
        public void CanAddAndRetrieveInstructor()
        {
            using var context = TestDbContextFactory.Create();

            context.Instructors.Add(new Instructor
            {
                LastName = "Prof",
                FirstMidName = "Test",
                HireDate = new DateTime(2020, 1, 1),
                CourseAssignments = new List<CourseAssignment>()
            });
            context.SaveChanges();

            var instructor = context.Instructors.First();
            Assert.Equal("Prof", instructor.LastName);
            Assert.Equal("Prof, Test", instructor.FullName);
        }

        [Fact]
        public void CanAddEnrollmentWithRelationships()
        {
            using var context = TestDbContextFactory.CreateWithSeedData();

            var enrollment = new Enrollment
            {
                CourseID = 101,
                StudentID = 1,
                Grade = Grade.A
            };
            context.Enrollments.Add(enrollment);
            context.SaveChanges();

            var result = context.Enrollments
                .Include(e => e.Course)
                .Include(e => e.Student)
                .Last();

            Assert.Equal("Intro to CS", result.Course.Title);
            Assert.Equal("Doe", result.Student.LastName);
        }

        [Fact]
        public void CourseAssignment_HasCompositeKey()
        {
            using var context = TestDbContextFactory.CreateWithSeedData();

            var ca = context.CourseAssignments.Find(101, 1);
            Assert.NotNull(ca);
        }

        [Fact]
        public void OfficeAssignment_OneToOneWithInstructor()
        {
            using var context = TestDbContextFactory.Create();

            var instructor = new Instructor
            {
                ID = 10,
                LastName = "Office",
                FirstMidName = "Prof",
                HireDate = new DateTime(2020, 1, 1),
                CourseAssignments = new List<CourseAssignment>(),
                OfficeAssignment = new OfficeAssignment
                {
                    InstructorID = 10,
                    Location = "Room 101"
                }
            };
            context.Instructors.Add(instructor);
            context.SaveChanges();

            var result = context.Instructors
                .Include(i => i.OfficeAssignment)
                .First(i => i.ID == 10);

            Assert.NotNull(result.OfficeAssignment);
            Assert.Equal("Room 101", result.OfficeAssignment.Location);
        }

        [Fact]
        public void Student_InheritsFromPerson()
        {
            using var context = TestDbContextFactory.CreateWithSeedData();

            var student = context.Students.First();
            Assert.IsAssignableFrom<Person>(student);
            Assert.NotNull(student.FullName);
            Assert.Contains(",", student.FullName);
        }

        [Fact]
        public void Department_CanHaveNullAdministrator()
        {
            using var context = TestDbContextFactory.Create();

            var dept = new Department
            {
                DepartmentID = 50,
                Name = "No Admin",
                Budget = 5000,
                StartDate = DateTime.Now,
                InstructorID = null
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var result = context.Departments.Find(50);
            Assert.Null(result!.InstructorID);
        }

        [Fact]
        public void Enrollment_GradeCanBeNull()
        {
            using var context = TestDbContextFactory.Create();

            context.Students.Add(new Student
            {
                ID = 100,
                LastName = "Null",
                FirstMidName = "Grade",
                EnrollmentDate = DateTime.Now,
                Enrollments = new List<Enrollment>()
            });
            context.Departments.Add(new Department { DepartmentID = 99, Name = "D", Budget = 0, StartDate = DateTime.Now });
            context.Courses.Add(new Course
            {
                CourseID = 999,
                Title = "NullGrade",
                Credits = 1,
                DepartmentID = 99,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            });
            context.SaveChanges();

            context.Enrollments.Add(new Enrollment
            {
                CourseID = 999,
                StudentID = 100,
                Grade = null
            });
            context.SaveChanges();

            var enrollment = context.Enrollments.First(e => e.CourseID == 999);
            Assert.Null(enrollment.Grade);
        }
    }
}

