        public void Department_CanHaveNullAdministrator()
        {
            using var context = TestDbContextFactory.Create();

            var dept = new Department
            {
                DepartmentID = 50,
                Name = "No Admin",
                Budget = 5000,
                StartDate = DateTime.Now,
                InstructorID = null
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var result = context.Departments.Find(50);
            Assert.Null(result!.InstructorID);
        }

        [Fact]
        public void Enrollment_GradeCanBeNull()
        {
            using var context = TestDbContextFactory.Create();

            context.Students.Add(new Student
            {
                ID = 100,
                LastName = "Null",
                FirstMidName = "Grade",
                EnrollmentDate = DateTime.Now,
                Enrollments = new List<Enrollment>()
            });
            context.Departments.Add(new Department { DepartmentID = 99, Name = "D", Budget = 0, StartDate = DateTime.Now });
            context.Courses.Add(new Course
            {
                CourseID = 999,
                Title = "NullGrade",
                Credits = 1,
                DepartmentID = 99,
                Enrollments = new List<Enrollment>(),
                CourseAssignments = new List<CourseAssignment>()
            });
            context.SaveChanges();

            context.Enrollments.Add(new Enrollment
            {
                CourseID = 999,
                StudentID = 100,
                Grade = null
            });
            context.SaveChanges();

            var enrollment = context.Enrollments.First(e => e.CourseID == 999);
            Assert.Null(enrollment.Grade);
        }
    }
}

