private static void SeedData(SchoolContext context)
{
    // Use non-overlapping IDs for Students and Instructors (TPH shares Person table)
    var instructor1 = new Instructor { LastName = "Smith", FirstMidName = "John", HireDate = new DateTime(2020, 1, 15), CourseAssignments = new List<CourseAssignment>() };
    var instructor2 = new Instructor { LastName = "Jones", FirstMidName = "Jane", HireDate = new DateTime(2019, 6, 1), CourseAssignments = new List<CourseAssignment>() };
    context.Instructors.AddRange(instructor1, instructor2);
    context.SaveChanges();

    var departments = new[]
    {
        new Department { DepartmentID = 1, Name = "Engineering", Budget = 100000m, StartDate = new DateTime(2020, 9, 1), InstructorID = instructor1.ID },
        new Department { DepartmentID = 2, Name = "Science", Budget = 50000m, StartDate = new DateTime(2019, 9, 1), InstructorID = instructor2.ID }
    };
    context.Departments.AddRange(departments);
    context.SaveChanges();

    var courses = new[]
    {
        new Course { CourseID = 101, Title = "Intro to CS", Credits = 3, DepartmentID = 1, Enrollments = new List<Enrollment>(), CourseAssignments = new List<CourseAssignment>() },
        new Course { CourseID = 102, Title = "Data Structures", Credits = 4, DepartmentID = 1, Enrollments = new List<Enrollment>(), CourseAssignments = new List<CourseAssignment>() },
        new Course { CourseID = 201, Title = "Physics 101", Credits = 3, DepartmentID = 2, Enrollments = new List<Enrollment>(), CourseAssignments = new List<CourseAssignment>() }
    };
    context.Courses.AddRange(courses);
    context.SaveChanges();

    var student1 = new Student { LastName = "Doe", FirstMidName = "Alice", EnrollmentDate = new DateTime(2021, 9, 1), Enrollments = new List<Enrollment>() };
    var student2 = new Student { LastName = "Brown", FirstMidName = "Bob", EnrollmentDate = new DateTime(2022, 1, 15), Enrollments = new List<Enrollment>() };
    var student3 = new Student { LastName = "Adams", FirstMidName = "Charlie", EnrollmentDate = new DateTime(2021, 9, 1), Enrollments = new List<Enrollment>() };
    context.Students.AddRange(student1, student2, student3);
    context.SaveChanges();

    var enrollments = new[]
    {
        new Enrollment { CourseID = 101, StudentID = student1.ID, Grade = Grade.A },
        new Enrollment { CourseID = 102, StudentID = student1.ID, Grade = Grade.B },
        new Enrollment { CourseID = 101, StudentID = student2.ID, Grade = Grade.C }
    };
    context.Enrollments.AddRange(enrollments);

    var courseAssignments = new[]
    {
        new CourseAssignment { CourseID = 101, InstructorID = instructor1.ID },
        new CourseAssignment { CourseID = 102, InstructorID = instructor1.ID },
        new CourseAssignment { CourseID = 201, InstructorID = instructor2.ID }
    };
    context.CourseAssignments.AddRange(courseAssignments);

    context.SaveChanges();
}

